INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri'), 5, 'Dettifoss', 'Europe''s most powerful waterfall.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=800&q=75');
