INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara'), 2, 'Night in a desert camp', 'Berber drums by the fire and more stars than you''ve ever seen.', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=800&q=75');
