INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira'), 2, 'Grilled fish at the port', 'Pick it from the stall, they grill it in front of you.', 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=800&q=75');
